import {editingReason,domainFor,globalIdField,verifiedDefault} from './core.js?v=20261015-template';
import {makePlan,savePlan,verifySaved,normalizeId} from './bulk.js?v=alert-edit-20261017';
import {valueControl} from './domain-controls.js?v=20261015-template';
import {missingKind} from './survey-checks.js?v=alert-edit-20261017';
export function assertAlertIdentity(meta,attrs,issue){const gid=globalIdField(meta);if(!gid||!attrs||attrs[meta.objectIdField]!==issue.objectId||normalizeId(attrs[gid.name])!==normalizeId(issue.globalId))throw Error('The current feature does not match the alert Global ID. Run a fresh check.');}
export function attachAlertEditor({$,state,auth,action,stop,current,onSaved}){let context=null,serial=0;
 function clear(){serial++;context=null;$('alert-edit-fields').replaceChildren();$('alert-edit-submit').disabled=true;$('alert-edit-status').textContent='Load the current feature to fill its missing monitored attributes. Submitting writes directly to the selected Utility Network service.';}
 async function load(){const issue=current(),version=serial,api=auth();if(!issue)throw Error('Open an alert first.');stop('Monitoring stopped while you edit. Start monitoring again after saving.');$('alert-edit-status').textContent='Checking current values, permissions and service version…';const layerMeta=await api.request(issue.url),meta={...layerMeta};meta.objectIdField||=meta.fields?.find(f=>f.type==='esriFieldTypeOID')?.name;if(!meta.objectIdField)throw Error('The service has no object ID field.');if(meta.isDataVersioned){meta.__editContext=verifiedDefault(await api.request(issue.url.replace(/\/FeatureServer\/\d+$/i,'/VersionManagementServer'),{},'GET'));meta.__editEnabled=true;api.versions.set(issue.url.replace(/\/\d+$/,''),meta.__editContext.versionName);}
 const rows=await api.records(issue.url,[issue.objectId],meta),attrs=rows[0]?.attributes;assertAlertIdentity(meta,attrs,issue);if(version!==serial||api!==auth()||current()!==issue)return;const inputs=[];$('alert-edit-fields').replaceChildren();for(const checked of issue.checkedAttributes||[]){if(!checked.kind)continue;const field=meta.fields.find(f=>f.name===checked.name),row=document.createElement('label'),note=document.createElement('span');row.textContent=checked.label+' ['+checked.name+']';if(!field){note.textContent='Field no longer exists.';}else if(!missingKind(attrs[field.name])){note.textContent='Already filled on the server. Run a fresh check.';}else{const reason=editingReason(field,meta,state.user,attrs);if(reason)note.textContent='Read-only: '+reason;else{const input=valueControl(field,domainFor(meta,field,attrs),'');input.setAttribute('aria-label','Fill '+(field.alias||field.name));input.placeholder='Enter a value; blank leaves unchanged';row.append(input);inputs.push({field,input});note.textContent=field.type==='esriFieldTypeDate'?'Use an ISO date/time with timezone.':'Blank leaves unchanged. Use an allowed domain value when provided.';}}row.append(note);$('alert-edit-fields').append(row);}
 context={api,meta,attrs,issue,inputs,version};$('alert-edit-submit').disabled=!inputs.length;$('alert-edit-status').textContent=inputs.length?'Edit '+inputs.length+' permitted missing attribute(s), then Submit changes to Utility Network. Target: '+(meta.__editContext?.versionName||'published service data')+'. Global ID: '+issue.globalId:'No missing monitored fields can currently be edited. Review the explanations above.';}
 $('alert-edit-load').onclick=()=>action(async()=>{try{clear();await load();}catch(e){$('alert-edit-status').textContent=e.message;throw e;}});
 $('alert-edit-form').onsubmit=e=>{e.preventDefault();action(async()=>{const c=context;if(!c||c.version!==serial||c.api!==auth()||current()!==c.issue)throw Error('Load the current missing attributes again.');$('alert-edit-submit').disabled=true;try{const values={};for(const {field,input} of c.inputs)if(input.value.trim()!=='')values[field.name]=input.value;const plan=makePlan([{globalId:normalizeId(c.issue.globalId),values}],[{attributes:c.attrs}],c.meta,state.user);if(plan.errors.length)throw Error(plan.errors.map(e=>e.join(': ')).join('\n'));if(!plan.records.length)throw Error('Enter at least one value to submit. Blank inputs leave values unchanged.');$('alert-edit-status').textContent='Submitting '+plan.records[0].changes.length+' field change(s)…';context=null;const results=await verifySaved(c.api,c.issue.url,c.meta,plan,await savePlan(c.api,c.issue.url,c.meta,state.user,plan)),result=results[0];if(c.version!==serial||c.api!==auth()||current()!==c.issue)return;if(result.status!=='Saved and verified'){context=null;throw Error(result.status+': '+result.detail+' Load current values before trying again.');}const rows=await c.api.records(c.issue.url,[c.issue.objectId],c.meta);assertAlertIdentity(c.meta,rows[0]?.attributes,c.issue);if(c.version!==serial||c.api!==auth()||current()!==c.issue)return;await onSaved(c.issue,c.meta,rows[0].attributes,plan.records[0].changes);clear();$('alert-edit-status').textContent='Saved and verified in Utility Network: '+plan.records[0].changes.length+' field(s). This alert now shows fresh values. Run Check now to refresh the result list, or restart monitoring.';}catch(error){$('alert-edit-status').textContent=error.message;throw error;}finally{$('alert-edit-submit').disabled=!context;}});};
 $('monitor-issue-dialog').addEventListener('close',clear);clear();return {clear};}
